// Hand-written `telegraf` stub for the flowatlas fixture suite.
//
// The receiver's type is the only signal that separates a bot from any other
// object with a method called `on`, so the adapter needs the class to resolve
// to this package. Only the shapes it matches on are declared.

export type Trigger = string | RegExp;

export declare class Telegraf {
  start(handler: (ctx: unknown) => unknown): void;
  help(handler: (ctx: unknown) => unknown): void;
  settings(handler: (ctx: unknown) => unknown): void;
  command(trigger: Trigger | Trigger[], handler: (ctx: unknown) => unknown): void;
  hears(trigger: Trigger | Trigger[], handler: (ctx: unknown) => unknown): void;
  action(trigger: Trigger | Trigger[], handler: (ctx: unknown) => unknown): void;
  on(update: string, handler: (ctx: unknown) => unknown): void;
  launch(): void;
}
